/// <summary>
/// Extension of InventItemBarcode table.
/// </summary>
[ExtensionOf(tableStr(InventItemBarcode))]
final class METInventItemBarcode_Extension
{
}

Method.Source:
    /// <summary>
    /// Method to set the METDefault to No for the item barcodes
    /// </summary>
    /// <param name = "_inventItemBarcode">A <t>InventItemBarcode</t> buffer</param>
    public static void METUpdateDefaultForItemBarcode(InventItemBarcode _inventItemBarcode)
    {
        InventItemBarcode   inventItemBarcodeLoc;

        ttsbegin;

        update_recordset inventItemBarcodeLoc
            setting METDefault = NoYes::No
                where inventItemBarcodeLoc.itemId == _inventItemBarcode.itemId
                   && inventItemBarcodeLoc.UnitID == _inventItemBarcode.UnitID
                   && inventItemBarcodeLoc.RecId != _inventItemBarcode.RecId;

        ttscommit;
    }

    /// <summary>
    /// Method to find a <t>InventItemBarcode</t> buffer
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_inventDimCriteria">A <t>inventDim</t>buffer</param>
    /// <param name = "_onlyPrint">boolean value to indicate if it used only for printing</param>
    /// <param name = "_onlyInput">boolean value to indicate if it used only for input</param>
    /// <param name = "_barcodeSetupId">Barcode ID</param>
    /// <param name = "_unitId">the unit of measure symbol</param>
    /// <param name = "_update">boolean value to indicate if the record is to be updated</param>
    /// <returns>A <t>InventItemBarcode</t> buffer</returns>
    public static InventItemBarcode findByProductDimensions(
        ItemId              _itemId,
        InventDim           _inventDimCriteria,
        boolean             _onlyPrint,
        boolean             _onlyInput,
        BarcodeSetupId      _barcodeSetupId,
        UnitOfMeasureSymbol _unitId,
        boolean             _update)
    {
        InventItemBarcode   inventItemBarcode;
        InventDim           inventDim;
        InventDimParm       inventDimParm;
        inventDimParm = EcoResProductDimGroupSetup::newItemId(_itemId).inventDimParmActiveDimensions();

        next findByProductDimensions(_itemId,
                                     _inventDimCriteria,
                                     _onlyPrint,
                                     _onlyInput,
                                     _barcodeSetupId,
                                     _unitId,
                                     _update);

        inventItemBarcode.selectForUpdate(_update);
        if (_barcodeSetupId)
        {
            if (_onlyPrint && _onlyInput)
            {
                select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                       && inventItemBarcode.BarcodeSetupId  == _barcodeSetupId
                       && (!_unitId || inventItemBarcode.UnitID == _unitId)
                       && inventItemBarcode.UseForPrinting  == NoYes::Yes
                       && inventItemBarcode.UseForInput     == NoYes::Yes
                       && inventItemBarcode.METDefault      == NoYes::Yes
                    #InventDimExistsJoin(inventItemBarcode.inventDimId, inventDim, _inventDimCriteria, inventDimParm);
            }
            else if (_onlyPrint)
            {
                select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                       && inventItemBarcode.BarcodeSetupId  == _barcodeSetupId
                       && (!_unitId || inventItemBarcode.UnitID == _unitId)
                       && inventItemBarcode.UseForPrinting  == NoYes::Yes
                       && inventItemBarcode.METDefault      == NoYes::Yes
                    #InventDimExistsJoin(inventItemBarcode.inventDimId, inventDim, _inventDimCriteria, inventDimParm);
            }
            else if (_onlyInput)
            {
                select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                       && inventItemBarcode.BarcodeSetupId  == _barcodeSetupId
                       && (!_unitId || inventItemBarcode.UnitID == _unitId)
                       && inventItemBarcode.UseForInput     == NoYes::Yes
                       && inventItemBarcode.METDefault      == NoYes::Yes
                    #InventDimExistsJoin(inventItemBarcode.inventDimId, inventDim, _inventDimCriteria, inventDimParm);
            }
            else
            {
                select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                       && inventItemBarcode.BarcodeSetupId  == _barcodeSetupId
                       && (!_unitId || inventItemBarcode.UnitID == _unitId)
                       && inventItemBarcode.METDefault      == NoYes::Yes
                    #InventDimExistsJoin(inventItemBarcode.inventDimId, inventDim, _inventDimCriteria, inventDimParm);
            }
        }
        else
        {
            if (_onlyPrint && _onlyInput)
            {
                select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                       && (!_unitId || inventItemBarcode.UnitID == _unitId)
                       && inventItemBarcode.UseForPrinting  == NoYes::Yes
                       && inventItemBarcode.UseForInput     == NoYes::Yes
                       && inventItemBarcode.METDefault      == NoYes::Yes
                    #InventDimExistsJoin(inventItemBarcode.inventDimId, inventDim, _inventDimCriteria, inventDimParm);
            }
            else if (_onlyPrint)
            {
                select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                       && (!_unitId || inventItemBarcode.UnitID == _unitId)
                       && inventItemBarcode.UseForPrinting  == NoYes::Yes
                       && inventItemBarcode.METDefault      == NoYes::Yes
                    #InventDimExistsJoin(inventItemBarcode.inventDimId, inventDim, _inventDimCriteria, inventDimParm);
            }
            else if (_onlyInput)
            {
                select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                       && (!_unitId || inventItemBarcode.UnitID == _unitId)
                       && inventItemBarcode.UseForInput     == NoYes::Yes
                       && inventItemBarcode.METDefault      == NoYes::Yes
                    #InventDimExistsJoin(inventItemBarcode.inventDimId, inventDim, _inventDimCriteria, inventDimParm);
            }
            else
            {
                select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                       && (!_unitId || inventItemBarcode.UnitID == _unitId)
                       && (!_unitId || inventItemBarcode.METDefault      == NoYes::Yes)
                    #InventDimExistsJoin(inventItemBarcode.inventDimId, inventDim, _inventDimCriteria, inventDimParm);
            }
        }
        return inventItemBarcode;
    }

    /// <summary>
    ///  Method to find a <t>InventItemBarcode</t> buffer
    /// </summary>
    /// <param name = "itemId">Item Id</param>
    /// <param name = "onlyPrint">boolean value to indicate if it used only for printing</param>
    /// <param name = "onlyInput">boolean value to indicate if it used only for input</param>
    /// <param name = "barcodeSetupId">Barcode ID</param>
    /// <param name = "_update">boolean value to indicate if the record is to be updated</param>
    /// <returns>A <t>InventItemBarcode</t> buffer</returns>
    public static InventItemBarcode findItemId(
        ItemId              itemId,
        boolean             onlyPrint,
        boolean             onlyInput,
        BarcodeSetupId      barcodeSetupId,
        boolean             _update)
    {
        InventItemBarcode   inventItemBarcode;
        InventTableModule   inventTableModule;

        next findItemId(itemId,
                        onlyPrint,
                        onlyInput,
                        barcodeSetupId,
                        _update);

        select firstonly UnitId from inventTableModule
            where inventTableModule.ItemId == itemId
            && inventTableModule.ModuleType == ModuleInventPurchSales::Sales
            && inventTableModule.DataAreaId == curExt();

        inventItemBarcode.selectForUpdate(_update);

        if (barcodeSetupId)
        {
            if (onlyPrint && onlyInput)
            {
                select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == itemId           &&
                          inventItemBarcode.BarcodeSetupId  == barcodeSetupId   &&
                          inventItemBarcode.UseForPrinting  == NoYes::Yes       &&
                          inventItemBarcode.UseForInput     == NoYes::Yes       &&
                          inventItemBarcode.InventDimId     == InventDim::inventDimIdBlank()  &&
                          inventItemBarcode.UnitID          == inventTableModule.UnitId &&
                          inventItemBarcode.METDefault      == NoYes::Yes;

            }
            else if (onlyPrint)
            {
                select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == itemId           &&
                          inventItemBarcode.BarcodeSetupId  == barcodeSetupId   &&
                          inventItemBarcode.UseForPrinting  == NoYes::Yes       &&
                          inventItemBarcode.InventDimId     == InventDim::inventDimIdBlank()  &&
                          inventItemBarcode.UnitID          == inventTableModule.UnitId &&
                          inventItemBarcode.METDefault      == NoYes::Yes;
            }
            else if (onlyInput)
            {
                select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == itemId           &&
                          inventItemBarcode.BarcodeSetupId  == barcodeSetupId   &&
                          inventItemBarcode.UseForInput     == NoYes::Yes       &&
                          inventItemBarcode.InventDimId     == InventDim::inventDimIdBlank()  &&
                          inventItemBarcode.UnitID          == inventTableModule.UnitId &&
                          inventItemBarcode.METDefault      == NoYes::Yes;
            }
            else
            {
                select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == itemId           &&
                          inventItemBarcode.BarcodeSetupId  == barcodeSetupId   &&
                          inventItemBarcode.InventDimId     == InventDim::inventDimIdBlank()  &&
                          inventItemBarcode.UnitID          == inventTableModule.UnitId &&
                          inventItemBarcode.METDefault      == NoYes::Yes;
            }
        }
        else
        {
            if (onlyPrint && onlyInput)
            {
                select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == itemId       &&
                          inventItemBarcode.UseForPrinting  == NoYes::Yes   &&
                          inventItemBarcode.UseForInput     == NoYes::Yes   &&
                          inventItemBarcode.InventDimId     == InventDim::inventDimIdBlank()  &&
                          inventItemBarcode.UnitID          == inventTableModule.UnitId &&
                          inventItemBarcode.METDefault      == NoYes::Yes;
            }
            else if (onlyPrint)
            {
                select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == itemId       &&
                          inventItemBarcode.UseForPrinting  == NoYes::Yes   &&
                          inventItemBarcode.InventDimId     == InventDim::inventDimIdBlank()  &&
                          inventItemBarcode.UnitID          == inventTableModule.UnitId &&
                          inventItemBarcode.METDefault      == NoYes::Yes;
            }
            else if (onlyInput)
            {
                select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == itemId       &&
                          inventItemBarcode.UseForInput     == NoYes::Yes   &&
                          inventItemBarcode.InventDimId     == InventDim::inventDimIdBlank()  &&
                          inventItemBarcode.UnitID          == inventTableModule.UnitId &&
                          inventItemBarcode.METDefault      == NoYes::Yes;
            }
            else
            {
                select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == itemId       &&
                          inventItemBarcode.InventDimId     == InventDim::inventDimIdBlank()  &&
                          inventItemBarcode.UnitID          == inventTableModule.UnitId &&
                          inventItemBarcode.METDefault      == NoYes::Yes;
            }
        }

        return inventItemBarcode;
    }
